def JointExistence : Prop := ∀ g : GaugeGroup, g.IsSimple → ∃ C : WilsonFamily g,
  WilsonRegularity C ∧ ∀ p : ℕ → ℕ, StrictMono p → ∃ q : ℕ → ℕ, StrictMono q ∧
    ∃ T : Hierarchy C, T.Properties (p ∘ q)

theorem answer : YM.Bid.G03 := by
  intro G H d peg
  let r {m : ℕ} (B : Fin m → Slot) := Module.finrank ℝ (kernel H d B)
  let s : Set ℕ := {k | ∃ (m : ℕ) (B : Fin m → Slot), r B = k}
  obtain ⟨n,⟨m,B,rfl⟩,hmin⟩ := wellFounded_lt.has_min s ⟨_,0,Fin.elim0,rfl⟩
  refine ⟨m,B,fun A ha => detects_all H d peg A (fun b => ?_)⟩

def meanPartial (A : Taylor G k) (i j : Axis) (x : E4) (t : ℝ) :=
  ∫ s : ℝ in 0..1, ∫ r : ℝ in 0..1,
    Maxwell.grad i (A.value j) (x + (t*s) • basis j + (t*r) • basis i)

def Cumuli (H : Hol G) (d : ℕ) (F : Labels.Frame G d) {m} (B : Fin m → Slot) (P : F.Index → Pose G m) : Prop :=
    P 0=1 ∧ (∀ i u x, lumin (P i) (rotates u x)=lumin (P i) x) ∧ (∀ i x,star (lumin (P i) x)=lumin (P i) x) ∧
        (∀ i, Projects H (F.basis i) (lumin (P i) ∘ mapped B)) ∧ ∀ i,lows (P i) (F.grades i).2

def Projects {d : ℕ} (H : Hol G) (p : Label G d) (F : CoverConfig G → ℂ) := ∀ J : Jet G,
    let f := fun h => F (H.links d J h)
    let g := fun h => read (scaleJet J h) p.val
    ContDiffAt ℝ (d : ℕ∞) f 0 ∧ ContDiffAt ℝ (d : ℕ∞) g 0 ∧
      ∀ k ≤ d, iteratedDeriv k f 0 = iteratedDeriv k g 0

def Projects {d : ℕ} (H : Hol G) (p : Label G d) (F : CoverConfig G → ℂ) := ∀ J : Jet G,
    let f := fun h => F (H.links d J h)
    let g := fun h => read (scaleJet J h) p.val
    ContDiffAt ℝ (d : ℕ∞) f 0 ∧ ContDiffAt ℝ (d : ℕ∞) g 0 ∧
      ∀ k ≤ d, iteratedDeriv k f 0 = iteratedDeriv k g 0

def flux (V : Links R G.El) (e : Edge (Four R)) (p : PlaqAxes) :=
    if p.val.1=e.2 then stem V e.1 p.val.2 p
    else if p.val.2=e.2 then -(stem V e.1 p.val.1 p) else 0

def MicroAt (f : Pre G) (r M : ℕ) := ∀ n : Side, M ≤ n.val → ∀ o : Site n,
    ∀ β : ℝ, β ≠ 0 → ∀ S : Config G n → ℂ, LocalOn (Outer r o) S → RG.Envelope S →
    moment β (fun U => f (expandAt o U) * S U)=0

private lemma safe_top (A : Jet G) (k : ℕ)
    (h : ∀ i j : Axis, i < j → ∃ X : Set Cover, X.Finite ∧ ∀ x : Cover, x∉X →
      ∑ l ∈ Finset.range (k+1), net (A l) i j (castPos x) 1 = 0) : A k=0 := by

private lemma avg_shift (A : Taylor G j) (a b i : Axis) (z : E4) (t : ℝ) :
    t • (∫ u : ℝ in 0..1, Maxwell.grad i (Maxwell.grad a (A.value b)) (z+(t*(u-1)) • basis i)) =
      Maxwell.grad a (A.value b) z - Maxwell.grad a (A.value b) (z-t • basis i) := by

def curlFactor (L : Side) (X : Finset Cover) (C : ℝ) : ℝ :=
  (2 * C^2) * (Fintype.card (Site L):ℝ) * (Fintype.card Axis:ℝ) *
    ((X.card:ℝ) * (Fintype.card PlaqAxes:ℝ)) * (X.card:ℝ)

def Comptroller (H : Forest S.ratio) (B : Bed) (p : Clip) (W : PathData G) := ∀ k : S.Choices,
    let f := Function.uncurry (tested H k p W)
    f 0=0 ∧ fderiv ℝ f 0=0 ∧ ∀ a b, iteratedFDeriv ℝ 2 f 0 ![a,b]=
      gaugeFiscal B (stretch H a) (stretch H b) + S.kernel.penalty * ∑ i : Body 1 c, inner ℝ (crop H a i) (crop H b i)

lemma velvet_sized (L : Needle (Ports n t) (Loc G 1) n) {Φ : Bridge G P} (h : Cruise Φ 2 σ D) (hs : 0<σ) (hw : σ ≤ 1) (ht : Dai L (inch P.L*σ) C) (hc : 0≤C) (he : t≤2) (hz : (n+1)+t=4+u) :
    let U := textBare (P:=P) L (winglet n t)
    Pungent U σ ∧ Laureate U Φ σ (inch P.L^u * giftBay G n (Ports n t) D σ C) := by

def rind (p : Clip) (R : PathData G) (μ : ℝ) : Link G c :=
  let A := legion S t p R μ K V U
  ∑ i, ∑ j, (A⁻¹ i j) • (lapel S t K U j i)

private lemma unroll (i : Axis) (A : Weight L) (V : Chamber S i) (Q : Finset Axis) (h : Profile) (f : Grouping)
    (hv : Runs (ν V A) i 1 (stamp h)) :
    Tendsto (fun n => pay (ν V A) i Finset.univ h (cloud f Q n)) atTop (𝓝 (pay (ν V A) i Q h f)) := by
